function Parent() {
  const [text, setText] = useState('');
  // `handleSave` is a new function reference every render
  const handleSave = () => api.save(text);
  return <MemoizedChild onSave={handleSave} />;
}

// Child is memoized but still re-renders
const MemoizedChild = React.memo(function Child({ onSave }) {
  console.log('child rendered'); // fires on every keystroke
  return <button onClick={onSave}>Save</button>;
});

function Parent() {
  const [text, setText] = useState('');
  const handleSave = useCallback(() => api.save(text), [text]);
  return <MemoizedChild onSave={handleSave} />;
}

// Now the child only re-renders when `text` actually changes
const MemoizedChild = React.memo(function Child({ onSave }) {
  console.log('child rendered');
  return <button onClick={onSave}>Save</button>;
});

