function Page() {
  const [filter, setFilter] = useState('');
  // ExpensiveContent re-renders on every filter keystroke
  return (
    <div>
      <input value={filter} onChange={e => setFilter(e.target.value)} />
      <ExpensiveContent filter={filter} />
    </div>
  );
}

// Better: local state stays in the input component
function FilterPanel({ onApply }) {
  const [draft, setDraft] = useState('');
  return (
    <input
      value={draft}
      onChange={e => setDraft(e.target.value)}
      onBlur={() => onApply(draft)}
    />
  );
}
